public sealed class GetOrderStatusTool : McpTool
{
    public override string Name => "get_order_status";
    public override string Description => "Return the fulfillment status of an order by ID. Use this when the user asks where their order is.";

    public override McpParameterSchema Parameters => new(
        McpType.Object,
        new Dictionary<string, McpParameterSchema>(StringComparer.OrdinalIgnoreCase)
        {
            ["orderId"] = new McpParameterSchema(McpType.String)
            {
                Description = "The order identifier returned after checkout.",
                Required = true
            },
            ["includeTracking"] = new McpParameterSchema(McpType.Boolean)
            {
                Description = "Include tracking numbers if available.",
                Required = false,
                Default = false
            }
        });

    public async Task<McpToolResult> ExecuteAsync(
        McpParameterBag args,
        CancellationToken ct = default)
    {
        var orderId = args.GetString("orderId");
        var includeTracking = args.GetBool("includeTracking") ?? false;

        if (string.IsNullOrWhiteSpace(orderId))
            return McpToolResult.Error("orderId is required.");

        var order = await _orders.GetByPublicIdAsync(orderId, ct);
        if (order is null)
            return McpToolResult.NotFound("Order not found.");

        var payload = new
        {
            order.Status,
            order.EstimatedDelivery,
            Tracking = includeTracking ? order.TrackingNumbers : null
        };

        return McpToolResult.Success(JsonSerializer.Serialize(payload));
    }
}
